const meta=$('Validate Request').first().json;
const projRows=$('Prefetch Project Info').all().map(i=>i.json).filter(r=>r&&typeof r==='object'&&!r.code);
const taskRows=$('Prefetch Tasks').all().map(i=>i.json).filter(r=>r&&typeof r==='object'&&!r.code);
const apprRows=$('Prefetch Approvals').all().map(i=>i.json).filter(r=>r&&typeof r==='object'&&!r.code);
const wfRows=$('Prefetch Workflow Audits').all().map(i=>i.json).filter(r=>r&&typeof r==='object'&&!r.code);
const project=projRows.length>0?projRows[0]:null;
let tasks=taskRows;
let approvals=apprRows;
if(meta.since_date){const cutoff=new Date(meta.since_date).getTime();tasks=taskRows.filter(t=>{const ts=t.updated_at?new Date(t.updated_at).getTime():(t.created_at?new Date(t.created_at).getTime():0);return ts>=cutoff;});approvals=apprRows.filter(a=>{const ts=a.created_at?new Date(a.created_at).getTime():0;return ts>=cutoff;});}
const taskIds=new Set(tasks.map(t=>t.id).filter(Boolean));
const relevantApprovals=approvals.filter(a=>taskIds.has(a.task_id));
return [{json:{...meta,_project:project,_tasks:tasks,_approvals:relevantApprovals,_workflow_audits:wfRows}}];

const x=$input.first().json;const meta={request_id:x.request_id,user_id:x.user_id,workspace_id:x.workspace_id,project_id:x.project_id,conversation_id:x.conversation_id,has_project:x.has_project,since_date:x.since_date,token_check_status:x.token_check_status};const project=x._project||null;const tasks=x._tasks||[];const approvals=x._approvals||[];const workflowAudits=x._workflow_audits||[];
const completed=[],pending=[],blocked=[],failed=[];
for(const t of tasks){const s=String(t.status||'').toLowerCase();if(s==='completed'){completed.push(t);}else if(s==='failed'||s==='cancelled'){failed.push(t);}else if(s==='paused'||s==='blocked'||t.blocked_reason){blocked.push(t);}else{pending.push(t);}}
const total=tasks.length;const projectName=project?(project.name||project.title||project.slug||project.id):null;
let projectSummary='';
if(!meta.has_project){projectSummary='No specific project selected. Please provide project_id to view project progress.';}
else if(!project){projectSummary='Project '+meta.project_id+' not found. '+total+' orphaned task record(s) referenced.';}
else if(total===0){projectSummary='Project "'+(projectName||meta.project_id)+'": No tasks recorded yet.';}
else{const pct=Math.round((completed.length/total)*100);projectSummary='Project "'+(projectName||meta.project_id)+'": '+total+' task(s) total, '+completed.length+' completed ('+pct+'%), '+pending.length+' pending, '+blocked.length+' blocked, '+failed.length+' failed.';}
const verifyCount={completed:0,partial:0,failed:0,pending:0,other:0};
for(const w of workflowAudits){const s=String(w.audit_status||'').toLowerCase();if(s==='completed')verifyCount.completed++;else if(s==='partial')verifyCount.partial++;else if(s==='failed')verifyCount.failed++;else if(s==='pending')verifyCount.pending++;else verifyCount.other++;}
const mapTask=(t)=>({id:t.id||null,title:t.title||t.goal||null,status:t.status||null,priority:t.priority||null,due_date:t.due_date||null,blocked_reason:t.blocked_reason||null,updated_at:t.updated_at||t.created_at||null});
return [{json:{...meta,total_tasks:total,completed_count:completed.length,pending_count:pending.length,blocked_count:blocked.length,failed_count:failed.length,completed_tasks:completed.slice(0,50).map(mapTask),pending_tasks:pending.slice(0,50).map(mapTask),blocked_tasks:blocked.slice(0,50).map(mapTask),failed_tasks:failed.slice(0,50).map(mapTask),pending_approvals:approvals.length,workflow_audits_count:workflowAudits.length,workflow_audit_status_breakdown:verifyCount,project_name:projectName,project_summary:projectSummary}}];

const x=$input.first().json;const steps=[];
if(!x.has_project){steps.push({priority:'high',action:'Provide project_id',reason:'No project selected; cannot compute project-specific progress'});return [{json:{...x,recommended_next_steps:steps}}];}
if(!x.project_name){steps.push({priority:'high',action:'Verify project_id',reason:'Project record not found in database'});return [{json:{...x,recommended_next_steps:steps}}];}
if(x.total_tasks===0){steps.push({priority:'high',action:'Create initial tasks for this project',reason:'No tasks recorded yet'});return [{json:{...x,recommended_next_steps:steps}}];}
if(x.blocked_count>0)steps.push({priority:'critical',action:'Resolve '+x.blocked_count+' blocked task(s)',reason:'Blocked tasks halt project progress'});
if(x.failed_count>0)steps.push({priority:'important',action:'Review '+x.failed_count+' failed/cancelled task(s)',reason:'Failed tasks may indicate issues to address'});
if(x.pending_approvals>0)steps.push({priority:'important',action:'Process '+x.pending_approvals+' pending approval(s)',reason:'Approvals blocking task transitions'});
if(x.pending_count>0)steps.push({priority:'normal',action:'Continue '+x.pending_count+' pending task(s)',reason:'Work in progress'});
if(x.completed_count===x.total_tasks)steps.push({priority:'info',action:'Project appears complete',reason:'All tasks marked completed'});
return [{json:{...x,recommended_next_steps:steps}}];

const x = $input.first()?.json || {};
let valReq = {};
try {
  valReq = $('Validate Request').first()?.json || {};
} catch (e) {}

const reqId = valReq.request_id || x.request_id || 'fallback-id';
const userId = valReq.user_id || x.user_id || null;
const workspaceId = valReq.workspace_id || x.workspace_id || null;
const projectId = valReq.project_id ?? x.project_id ?? null;
const conversationId = valReq.conversation_id ?? x.conversation_id ?? null;
const hasProject = x.has_project ?? valReq.has_project ?? !!projectId;
const sinceDate = x.since_date ?? valReq.since_date ?? null;

const status = hasProject ? (x.project_name ? 'success' : 'partial') : 'failed';
const auditId = 'PROG-' + reqId;

const evidence = [];
if (sinceDate) evidence.push('since_date=' + sinceDate);
evidence.push('task_records=' + (x.total_tasks ?? 0) + ' completed=' + (x.completed_count ?? 0) + ' pending=' + (x.pending_count ?? 0) + ' blocked=' + (x.blocked_count ?? 0) + ' failed=' + (x.failed_count ?? 0));
evidence.push('pending_approvals=' + (x.pending_approvals ?? 0) + ' workflow_audits=' + (x.workflow_audits_count ?? 0));
evidence.push('Source: Supabase tables (tasks, approval_records, workflow_audits, projects); AI not used');

const limitations = [
  'Progress computed from persisted task records only; no AI estimation used (blueprint §17).',
  'Task records fetched from Supabase tasks table filtered by project_id + workspace_id; ordered by updated_at desc.',
  'Approvals filtered by task_ids derived from project tasks; workspace-scoped approvals fetched up to 500.',
  'Workflow audit status breakdown included as informational field.',
  'Cross-project aggregation not supported; single project_id per request.',
  'Recommended next steps are rule-based; not AI-generated.',
  'Webhook authentication required (Header Auth).',
  'Idempotency: audit_id=PROG-<request_id>; repeated request_id → 409 VERSION_CONFLICT.'
];

const verificationSummary = {
  status: 'verified',
  evidence,
  source: 'database_task_records',
  ai_used: false
};

const recommendedFixes = [];
if (!hasProject) recommendedFixes.push({ finding_id: 'V001', fix: 'Provide project_id to compute progress' });

const result = {
  audit_id: auditId,
  audit_status: status,
  cache_hit: false,
  project_id: projectId,
  project_name: x.project_name || null,
  project_summary: x.project_summary || '',
  total_tasks: x.total_tasks ?? 0,
  completed_count: x.completed_count ?? 0,
  pending_count: x.pending_count ?? 0,
  blocked_count: x.blocked_count ?? 0,
  failed_count: x.failed_count ?? 0,
  completed_tasks: x.completed_tasks || [],
  pending_tasks: x.pending_tasks || [],
  blocked_tasks: x.blocked_tasks || [],
  failed_tasks: x.failed_tasks || [],
  pending_approvals: x.pending_approvals ?? 0,
  workflow_audits_count: x.workflow_audits_count ?? 0,
  workflow_audit_status_breakdown: x.workflow_audit_status_breakdown || { completed: 0, partial: 0, failed: 0, pending: 0, other: 0 },
  recommended_next_steps: x.recommended_next_steps || [],
  limitations,
  recommended_fixes: recommendedFixes,
  verification_summary: verificationSummary
};

const httpStatus = status === 'failed' ? 422 : 200;
const errors = [];
if (!hasProject) errors.push({ category: 'INVALID_INPUT', message: 'project_id required to compute project progress' });

const warnings = [];
if (hasProject && !x.project_name) warnings.push({ message: 'Project record not found; showing task summary only' });

return [{
  json: {
    request_id: reqId,
    task_id: null,
    status: status === 'success' ? 'completed' : (status === 'partial' ? 'partial' : 'failed'),
    _http_status: httpStatus,
    result,
    errors,
    warnings,
    verification: verificationSummary,
    _persist: {
      project_id: projectId,
      user_id: userId,
      claimed_user_id: userId,
      workspace_id: workspaceId,
      conversation_id: conversationId
    }
  }
}];

let src = null;
try {
  if ($('Build Result').isExecuted) {
    src = $('Build Result').first()?.json;
  }
} catch (e) {}
if (!src) {
  try {
    if ($('Format Request Error').isExecuted) {
      src = $('Format Request Error').first()?.json;
    }
  } catch (e) {}
}

let fallbackReqId = 'fallback-id';
try {
  fallbackReqId = $('Validate Request').first()?.json?.request_id || 'fallback-id';
} catch (e) {}

const reqId = src?.request_id || fallbackReqId;
const r = src?.result || {};
const auditId = r.audit_id || ('PROG-' + reqId);
const rows = [];

const pushTaskRow = (t, section) => {
  if (!t || !t.id) return;
  rows.push({
    audit_id: auditId,
    finding_id: 'T-' + section + '-' + String(t.id).slice(0, 30),
    severity: section === 'blocked' ? 'medium' : (section === 'failed' ? 'high' : 'info'),
    category: 'TASK_' + section.toUpperCase(),
    node_id: null,
    node_name: null,
    description: String(t.title || '(untitled)').slice(0, 300) + ' [' + (t.status || 'unknown') + ']',
    evidence: t.blocked_reason ? String(t.blocked_reason).slice(0, 500) : null,
    suggested_fix: null,
    confidence: null,
    knowledge_status: 'Verified',
    check_type: 'progress_task'
  });
};

for (const t of (r.completed_tasks || [])) pushTaskRow(t, 'completed');
for (const t of (r.pending_tasks || [])) pushTaskRow(t, 'pending');
for (const t of (r.blocked_tasks || [])) pushTaskRow(t, 'blocked');
for (const t of (r.failed_tasks || [])) pushTaskRow(t, 'failed');

if (rows.length === 0) {
  return [{ json: { _empty: true, audit_id: auditId, request_id: reqId } }];
}
return rows.map(x => ({ json: x }));

let src = null;
try {
  if ($('Build Result').isExecuted) {
    const a = $('Build Result').first()?.json;
    if (a && a.result) src = a;
  }
} catch (e) {}

if (!src) {
  try {
    if ($('Format Request Error').isExecuted) {
      const b = $('Format Request Error').first()?.json;
      if (b && b.result) src = b;
    }
  } catch (e) {}
}

let fallbackReqId = 'fallback-id';
try {
  fallbackReqId = $('Validate Request').first()?.json?.request_id || 'fallback-id';
} catch (e) {}

if (!src) {
  src = {
    request_id: fallbackReqId,
    status: 'failed',
    _http_status: 500,
    result: { audit_id: 'PROG-' + fallbackReqId, audit_status: 'failed' },
    verification: { status: 'not_verified', evidence: [] },
    errors: [],
    task_id: null,
    warnings: [],
    _persist: {}
  };
}
if (!src.request_id) src.request_id = fallbackReqId;

let headerRow = {};
try {
  headerRow = $('Persist Audit Header').first()?.json ?? {};
} catch (e) {}

const id = headerRow.id ?? headerRow.audit_id ?? src.result?.audit_id ?? null;
const idOk = typeof id === 'string' ? id.trim().length > 0 : (typeof id === 'number' && isFinite(id));
const checks = [];
if (!idOk) checks.push('no valid header record id');
if (headerRow.request_id !== undefined && headerRow.request_id !== null && src.request_id && headerRow.request_id !== src.request_id) {
  checks.push('request_id mismatch');
}

let batchRan = false;
try {
  batchRan = $('Persist Task Batch').isExecuted === true;
} catch (e) {}

if (batchRan) {
  const batchRows = $input.all().map(i => i.json).filter(r => r && (r.id || r.finding_id || r.audit_id));
  if (batchRows.length === 0) checks.push('task batch persist unconfirmed');
}

const ok = idOk && checks.length === 0;
const verification = { ...(src.verification || {}), persisted: ok, persist_record_id: idOk ? id : null, persist_checks: checks };
const result = { ...(src.result || {}), verification_summary: verification };

return [{
  json: {
    ...src,
    request_id: src.request_id || fallbackReqId,
    status: ok ? src.status : (src.status === 'failed' ? 'failed' : 'partial'),
    _http_status: src._http_status || 200,
    result,
    verification,
    errors: ok ? (src.errors || []) : [...(src.errors || []), { category: 'INTERNAL_ERROR', message: 'Persistence unconfirmed: ' + checks.join('; ') }],
    warnings: src.warnings || []
  }
}];

let src = null;
try {
  if ($('Build Result').isExecuted) {
    const a = $('Build Result').first()?.json;
    if (a && a.result) src = a;
  }
} catch (e) {}

if (!src) {
  try {
    if ($('Format Request Error').isExecuted) {
      const b = $('Format Request Error').first()?.json;
      if (b && b.result) src = b;
    }
  } catch (e) {}
}

let fallbackReqId = 'fallback-id';
try {
  fallbackReqId = $('Validate Request').first()?.json?.request_id || 'fallback-id';
} catch (e) {}

if (!src) {
  src = {
    request_id: fallbackReqId,
    status: 'failed',
    _http_status: 500,
    result: { audit_id: 'PROG-' + fallbackReqId, audit_status: 'failed' },
    verification: { status: 'not_verified', evidence: [] },
    errors: [],
    task_id: null,
    warnings: [],
    _persist: {}
  };
}
if (!src.request_id) src.request_id = fallbackReqId;

const raw = $input.first()?.json || {};
const rawStr = JSON.stringify(raw).toLowerCase();
const isDup = /23505|duplicate key|unique constraint/.test(rawStr);
const cat = isDup ? 'VERSION_CONFLICT' : 'INTERNAL_ERROR';
const msg = isDup ? 'Duplicate audit_id: this progress report already persisted (idempotent retry)' : ('Persistence failed: ' + String((raw.error && raw.error.message) || raw.message || 'unknown').slice(0, 200));
const origStatus = typeof src._http_status === 'number' ? src._http_status : 200;
const httpStatus = isDup ? 409 : (origStatus >= 400 ? origStatus : ((src.result && src.result.audit_status === 'failed') ? 422 : 500));

const verification = { ...(src.verification || {}), persisted: false, persist_record_id: null, persist_note: msg, idempotent_retry: isDup };
const result = { ...(src.result || {}), verification_summary: verification };

return [{
  json: {
    ...src,
    request_id: src.request_id || fallbackReqId,
    status: 'failed',
    _http_status: httpStatus,
    result,
    verification,
    errors: [...(src.errors || []), { category: cat, message: msg }],
    warnings: src.warnings || []
  }
}];
